// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, 1 ether * 1000);
        vm.deal(address(c), amount);
        uint256 callerBefore = address(this).balance;
        c.withdraw(amount);
        assertTrue(address(this).balance == callerBefore + amount && address(c).balance == 0);
    }
    receive() external payable {}
}
